export type SiteContent = {
  -readonly [K in keyof typeof DEFAULT_CONTENT]: DeepMutable<
    (typeof DEFAULT_CONTENT)[K]
  >
}

type DeepMutable<T> = T extends readonly (infer U)[]
  ? DeepMutable<U>[]
  : T extends object
    ? { -readonly [K in keyof T]: DeepMutable<T[K]> }
    : T
